-- Migration: 088_horizontal_project_lifecycle_archive.sql
-- 横向项目延期/暂停/终止、研究报告和合同档案留痕。
-- 本迁移只建立结构和约束，不插入示例项目、合同、金额或身份。
-- 迁移表沿用历史库的项目编号，不强加外键以免历史孤立记录阻断升级；应用写入前必须完成项目范围和启用人员校验。
BEGIN;

CREATE TABLE IF NOT EXISTS "横向项目生命周期申请" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "横向项目编号" integer NOT NULL,
    "事件类型" varchar(10) NOT NULL,
    "原合同结束日期" date,
    "新合同结束日期" date,
    "申请原因" varchar(2000) NOT NULL,
    "附件路径" varchar(1000),
    "状态" varchar(10) NOT NULL DEFAULT '待审核',
    "申请人编号" integer NOT NULL,
    "审核人编号" integer,
    "审核意见" varchar(2000),
    "申请时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "审核时间" timestamp without time zone,
    CONSTRAINT "pk_横向项目生命周期申请" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_横向项目生命周期申请_事件类型" CHECK ("事件类型" IN ('延期','暂停','终止')),
    CONSTRAINT "ck_横向项目生命周期申请_状态" CHECK ("状态" IN ('待审核','已批准','已驳回')),
    CONSTRAINT "ck_横向项目生命周期申请_延期日期" CHECK ("事件类型" <> '延期' OR "新合同结束日期" IS NOT NULL),
    CONSTRAINT "ck_横向项目生命周期申请_原因" CHECK (length(btrim("申请原因")) > 0)
);

CREATE INDEX IF NOT EXISTS "ix_横向项目生命周期申请_项目"
    ON "横向项目生命周期申请" ("横向项目编号", "申请时间" DESC);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_横向项目生命周期申请_待审核"
    ON "横向项目生命周期申请" ("横向项目编号", "事件类型")
    WHERE "状态" = '待审核';

CREATE TABLE IF NOT EXISTS "横向项目研究报告" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "横向项目编号" integer NOT NULL,
    "报告类型" varchar(30) NOT NULL,
    "报告年度" integer NOT NULL,
    "报告摘要" varchar(2000),
    "报告正文" text,
    "文件路径" varchar(1000),
    "状态" varchar(10) NOT NULL DEFAULT '草稿',
    "提交人编号" integer NOT NULL,
    "提交时间" timestamp without time zone,
    "审核人编号" integer,
    "审核意见" varchar(2000),
    "审核时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_横向项目研究报告" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_横向项目研究报告_项目类型年度" UNIQUE ("横向项目编号", "报告类型", "报告年度"),
    CONSTRAINT "ck_横向项目研究报告_状态" CHECK ("状态" IN ('草稿','待审核','已通过','已退回')),
    CONSTRAINT "ck_横向项目研究报告_年度" CHECK ("报告年度" BETWEEN 2000 AND 2200),
    CONSTRAINT "ck_横向项目研究报告_内容" CHECK (COALESCE(length(btrim("报告正文")), 0) > 0 OR COALESCE(length(btrim("文件路径")), 0) > 0)
);

CREATE INDEX IF NOT EXISTS "ix_横向项目研究报告_项目"
    ON "横向项目研究报告" ("横向项目编号", "报告年度" DESC, "建立时间" DESC);

CREATE TABLE IF NOT EXISTS "横向项目档案材料" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "横向项目编号" integer NOT NULL,
    "材料类型" varchar(50) NOT NULL,
    "材料标题" varchar(200) NOT NULL,
    "文件路径" varchar(1000) NOT NULL,
    "文件校验和" varchar(128),
    "版本号" integer NOT NULL DEFAULT 1,
    "是否必需" boolean NOT NULL DEFAULT FALSE,
    "状态" varchar(10) NOT NULL DEFAULT '有效',
    "上传人编号" integer NOT NULL,
    "上传时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_横向项目档案材料" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_横向项目档案材料_版本" UNIQUE ("横向项目编号", "材料类型", "版本号"),
    CONSTRAINT "ck_横向项目档案材料_版本号" CHECK ("版本号" > 0),
    CONSTRAINT "ck_横向项目档案材料_状态" CHECK ("状态" IN ('有效','作废')),
    CONSTRAINT "ck_横向项目档案材料_校验和" CHECK ("文件校验和" IS NULL OR "文件校验和" ~ '^[0-9A-Fa-f]{64}$'),
    CONSTRAINT "ck_横向项目档案材料_路径" CHECK (length(btrim("文件路径")) > 0)
);

CREATE INDEX IF NOT EXISTS "ix_横向项目档案材料_项目"
    ON "横向项目档案材料" ("横向项目编号", "材料类型", "版本号" DESC);

UPDATE "系统迁移版本"
   SET "版本" = 88,
       "脚本" = '088_horizontal_project_lifecycle_archive.sql',
       "检查摘要" = '增加横向项目延期暂停终止、研究报告和合同档案留痕',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;
COMMIT;
